'use strict';

// All Node/Prefab serialization below runs inside the actual Creator scene process.
// Asset content is generated by Creator's Prefab manager, never handwritten JSON.
const BLOCK = 'b730527c-3233-41c2-aaf7-7cdab58f9749@f9941';
const URL = 'db://assets/prefabs';

async function asset(cc, uuid, Type) {
    const value = await new Promise((resolve, reject) => cc.assetManager.loadAny(uuid,
        (error, loaded) => error ? reject(error) : resolve(loaded)));
    if (!(value instanceof Type)) throw new Error(`Unexpected asset type: ${uuid}`);
    return value;
}

exports.build = async function (cc) {
    const scene = cc.director.getScene();
    const canvas = scene && scene.getChildByName('Canvas');
    if (!canvas || !canvas.getComponent(cc.Canvas)?.cameraComponent) throw new Error('Open the existing Game.scene with its bound UI Camera first.');
    const editorEngine = globalThis.cce || globalThis.EditorExtends;
    if (!editorEngine?.Prefab?.generatePrefabDataFromNode) throw new Error('Creator Prefab serialization API is unavailable; no asset JSON will be fabricated.');
    const classes = {};
    for (const name of ['DraggableItem', 'CableConnector', 'GameController', 'RunController', 'LevelManager',
        'StageHost', 'DragMatchStageController', 'CableConnectStageController', 'CleanSwipeStageController']) {
        const Type = cc.js.getClassByName(name);
        if (!Type) throw new Error(`Wait for project scripts to import: ${name}`);
        classes[name] = Type;
    }
    const frame = await asset(cc, BLOCK, cc.SpriteFrame);
    const createdAssets = [];
    const reusedAssets = [];
    const temporary = [];
    function ui(parent, name, x, y, width, height) {
        const node = new cc.Node(name);
        node.layer = cc.Layers.Enum.UI_2D;
        node.setPosition(x, y, 0);
        node.addComponent(cc.UITransform).setContentSize(width, height);
        if (parent) node.parent = parent;
        return node;
    }
    function block(node, color) {
        const sprite = node.addComponent(cc.Sprite);
        sprite.sizeMode = cc.Sprite.SizeMode.CUSTOM;
        sprite.type = cc.Sprite.Type.SLICED;
        sprite.spriteFrame = frame;
        sprite.color = new cc.Color(...color);
    }
    function label(parent, name, x, y, width, height, size, text) {
        const node = parent.getChildByName(name) || ui(parent, name, x, y, width, height);
        node.setPosition(x, y, 0);
        node.getComponent(cc.UITransform).setContentSize(width, height);
        const value = node.getComponent(cc.Label) || node.addComponent(cc.Label);
        Object.assign(value, { string: text, fontSize: size, lineHeight: size + 8, useSystemFont: true,
            fontFamily: 'Microsoft YaHei', horizontalAlign: cc.HorizontalTextAlignment.CENTER,
            verticalAlign: cc.VerticalTextAlignment.CENTER, overflow: cc.Label.Overflow.SHRINK,
            enableWrapText: true, color: new cc.Color(239, 245, 250, 255) });
        return value;
    }
    async function folder(url) {
        if (!await Editor.Message.request('asset-db', 'query-asset-info', url)) {
            const made = await Editor.Message.request('asset-db', 'create-asset', url, null);
            if (!made) throw new Error(`Could not create asset folder ${url}`);
        }
    }
    async function prefab(name, category, make, component) {
        const url = `${URL}/${category}/${name}.prefab`;
        const existing = await Editor.Message.request('asset-db', 'query-asset-info', url);
        if (existing) {
            const loaded = await asset(cc, existing.uuid, cc.Prefab);
            if (!loaded.data || (component && !loaded.data.getComponent(component))) throw new Error(`Existing prefab has unexpected contents; preserved ${url}`);
            reusedAssets.push(url);
            return loaded;
        }
        const node = make();
        temporary.push(node);
        const generated = editorEngine.Prefab.generatePrefabDataFromNode(node);
        if (!generated?.prefabData) throw new Error(`Creator could not serialize ${name}`);
        const saved = await Editor.Message.request('asset-db', 'create-asset', url, generated.prefabData);
        if (!saved?.uuid) throw new Error(`Creator could not save ${name}`);
        createdAssets.push(url);
        return asset(cc, saved.uuid, cc.Prefab);
    }
    try {
        await folder(`${URL}/elements`);
        await folder(`${URL}/stages`);
        const dragItem = await prefab('DragItem', 'elements', () => {
            const node = ui(null, 'DragItem', 0, 0, 180, 140);
            block(node, [35, 112, 142, 255]);
            label(node, 'Label', 0, 0, 170, 100, 30, '设备');
            node.addComponent(classes.DraggableItem);
            return node;
        }, classes.DraggableItem);
        const target = await prefab('DragTarget', 'elements', () => {
            const node = ui(null, 'DragTarget', 0, 0, 180, 140);
            block(node, [57, 80, 100, 255]);
            label(node, 'Label', 0, 0, 170, 100, 25, '目标');
            return node;
        }, cc.Sprite);
        const port = await prefab('Port', 'elements', () => {
            const node = ui(null, 'Port', 0, 0, 130, 80);
            block(node, [57, 80, 100, 255]);
            label(node, 'Label', 0, 0, 120, 70, 22, '接口');
            return node;
        }, cc.Sprite);
        const cable = await prefab('Cable', 'elements', () => {
            const node = ui(null, 'Cable', 0, 0, 720, 800);
            const line = ui(node, 'Line', 0, 0, 720, 800).addComponent(cc.Graphics);
            line.lineWidth = 9;
            const anchor = ui(node, 'Anchor', 0, 0, 22, 22);
            block(anchor, [120, 156, 190, 255]);
            const head = ui(node, 'Head', 0, 0, 130, 80);
            block(head, [35, 112, 142, 255]);
            label(head, 'Label', 0, 0, 120, 70, 22, '线头');
            Object.assign(node.addComponent(classes.CableConnector), { head, line, anchor });
            return node;
        }, classes.CableConnector);
        const dirt = await prefab('DirtCell', 'elements', () => {
            const node = ui(null, 'DirtCell', 0, 0, 60, 60);
            block(node, [147, 124, 91, 255]);
            node.addComponent(cc.UIOpacity);
            return node;
        }, cc.UIOpacity);
        const dragStage = await prefab('DragMatchStage', 'stages', () => {
            const node = ui(null, 'DragMatchStage', 0, 0, 720, 800);
            const gameController = node.addComponent(classes.GameController);
            Object.assign(node.addComponent(classes.DragMatchStageController), { gameController, itemPrefab: dragItem, targetPrefab: target });
            return node;
        }, classes.DragMatchStageController);
        const cableStage = await prefab('CableConnectStage', 'stages', () => {
            const node = ui(null, 'CableConnectStage', 0, 0, 720, 800);
            Object.assign(node.addComponent(classes.CableConnectStageController), { cablePrefab: cable, portPrefab: port });
            return node;
        }, classes.CableConnectStageController);
        const cleanStage = await prefab('CleanSwipeStage', 'stages', () => {
            const node = ui(null, 'CleanSwipeStage', 0, 0, 720, 800);
            const surface = ui(node, 'InputSurface', 0, 0, 680, 560);
            block(surface, [42, 63, 75, 255]);
            const dirtLayer = ui(surface, 'DirtLayer', 0, 0, 680, 650);
            Object.assign(node.addComponent(classes.CleanSwipeStageController), { dirtCellPrefab: dirt, inputSurface: surface, dirtLayer });
            return node;
        }, classes.CleanSwipeStageController);
        if (cc.director.getScene() !== scene || !cc.isValid(canvas)) throw new Error('Open scene changed while importing assets. Assets retained; scene not modified.');
        const header = canvas.getChildByName('Header');
        const playArea = canvas.getChildByName('PlayArea');
        const panel = canvas.getChildByName('CompletePanel');
        const tutorial = canvas.getChildByName('TutorialHint');
        if (!header || !playArea || !panel || !tutorial) throw new Error('Expected existing Day 3 UI. No unrelated nodes will be replaced.');
        // Archive only the six known Day 3 elements. Preserve unrelated user nodes.
        let legacy = playArea.getChildByName('LegacyDay3');
        for (const name of ['Item1', 'Item2', 'Item3', 'Target1', 'Target2', 'Target3']) {
            const old = playArea.getChildByName(name);
            if (!old) continue;
            if (!legacy) legacy = ui(playArea, 'LegacyDay3', 0, 0, 720, 800);
            legacy.active = false;
            old.parent = legacy;
        }
        const oldController = canvas.getComponent(classes.GameController);
        if (oldController) { oldController.enabled = false; oldController.statusLabel = null; }
        const hostNode = playArea.getChildByName('StageHost') || ui(playArea, 'StageHost', 0, 0, 720, 800);
        hostNode.active = true;
        const host = hostNode.getComponent(classes.StageHost) || hostNode.addComponent(classes.StageHost);
        Object.assign(host, { dragMatchPrefab: dragStage, cableConnectPrefab: cableStage, cleanSwipePrefab: cleanStage });
        label(header, 'GameTitle', 0, 590, 660, 55, 40, '桌面急救站');
        const chapterLabel = label(header, 'ChapterLabel', 0, 545, 660, 32, 22, '基础订单');
        const levelLabel = label(header, 'LevelLabel', 0, 505, 660, 36, 25, '订单 1 / 9');
        const levelTitleLabel = label(header, 'LevelTitleLabel', 0, 462, 660, 44, 30, '桌面整理');
        const stageLabel = label(header, 'StageLabel', 0, 418, 660, 36, 22, '步骤 1 / 1');
        const statusLabel = label(header, 'StatusLabel', 0, 372, 660, 46, 23, '把设备拖到对应区域');
        const stats = header.getChildByName('Stats');
        const run = canvas.getComponent(classes.RunController);
        run.timeLabel = label(stats, 'TimeLabel', -170, 325, 300, 38, 22, '用时：0.0 秒');
        run.mistakeLabel = label(stats, 'MistakeLabel', 170, 325, 300, 38, 22, '失误：0');
        tutorial.setPosition(0, -510, 0);
        const tutorialLabel = label(tutorial, 'TutorialLabel', 0, 0, 580, 60, 25, '拖动物品到对应区域');
        panel.getComponent(cc.UITransform).setContentSize(660, 650);
        panel.setPosition(0, -20, 0);
        const completeLabel = label(panel, 'CompleteLabel', 0, 245, 620, 64, 36, '订单完成');
        const detail = label(panel, 'CompleteDetailLabel', 0, 15, 600, 340, 26, '');
        detail.lineHeight = 43;
        const buttonNode = panel.getChildByName('NextButton');
        buttonNode.setPosition(0, -245, 0);
        const button = buttonNode.getComponent(cc.Button);
        button.clickEvents = [];
        const action = label(buttonNode, 'Label', 0, 0, 280, 72, 30, '下一张订单');
        panel.active = false;
        const manager = canvas.getComponent(classes.LevelManager) || canvas.addComponent(classes.LevelManager);
        Object.assign(manager, { runController: run, stageHost: host, chapterLabel, levelLabel, levelTitleLabel,
            stageLabel, statusLabel, tutorialHint: tutorial, tutorialLabel, completePanel: panel,
            completeLabel, completeDetailLabel: detail, nextButton: button, actionButtonLabel: action });
        manager.enabled = true;
        return { ok: true, createdAssets, reusedAssets, sceneUuid: scene.uuid, stageHostUuid: hostNode.uuid,
            message: 'Day 4 Prefabs were generated by Creator and Inspector references updated.' };
    } finally {
        for (const node of temporary) if (cc.isValid(node)) node.destroy();
    }
};
